insert into lecture_examples (id, lecture_item_id, lang, position, eyebrow, title, bullets, panels) values (76, 30, 'he', 36, 'דוגמה מעשית', 'מעקב עלות לכל תכונה', ARRAY['עקוב אחר עלות לכל הפעלת תכונה ב-Supabase בכל הגרסאות', 'חשב את הממוצע הנגלל של 30 יום והשווה לתקציב המאושר', 'סמן גרסאות שבהן עלות להפעלה עולה על התקציב ביותר מ-10%']::text[], '[{"rows":[{"label":"INSERT COST RUN","value":"supabase.from(''ai_cost_runs'').insert({ release_id: ''v2.15.0'', feature: ''chat_assist'', input_tokens: 1280, output_tokens: 340, cost_usd: 0.0048, budget_usd: 0.004 })"},{"label":"OVER-BUDGET QUERY","value":"supabase.from(''ai_cost_runs'').select(''release_id, feature, cost_usd, budget_usd'').filter(''cost_usd'', ''gt'', ''budget_usd * 1.10'').order(''cost_usd'', { ascending: false })"},{"label":"RESULT","value":"[ { release_id: ''v2.15.0'', feature: ''chat_assist'', cost_usd: 0.0048, budget_usd: 0.004 } ] — 20% over budget"}],"verdict":{"status":"WARN","note":"chat_assist 20% מעל התקציב — ציון עלות נענש"}}]'::jsonb);
